const orderByPoints = (nums) => {
  const getSum = (num) => {
    const str = Math.abs(num).toString();
    let sum = 0;
    for (let char of str) {
      sum += parseInt(char, 10);
    }
    return sum;
  };

  return nums
    .map((val, index) => ({ val, index, sum: getSum(val) }))
    .sort((a, b) => {
      if (a.sum !== b.sum) {
        return a.sum - b.sum;
      }
      return a.index - b.index;
    })
    .map(item => item.val);
};

