const getMaxTriples = (n) => {
  let counts = [0, 0, 0];
  for (let i = 1; i <= n; i++) {
    let val = i * i - i + 1;
    counts[val % 3]++;
  }

  const c0 = counts[0];
  const c1 = counts[1];
  const c2 = counts[2];

  let total = 0;

  // Case 1: All three have the same remainder mod 3
  // 3*0 = 0, 3*1 = 3, 3*2 = 6 (all multiples of 3)
  if (c0 >= 3) total += (c0 * (c0 - 1) * (c0 - 2)) / 6;
  if (c1 >= 3) total += (c1 * (c1 - 1) * (c1 - 2)) / 6;
  if (c2 >= 3) total += (c2 * (c2 - 1) * (c2 - 2)) / 6;

  // Case 2: One of each remainder (0 + 1 + 2 = 3)
  total += c0 * c1 * c2;

  return total;
};

