const findMax = (words) => {
  if (!words || words.length === 0) return "";

  let maxWord = words[0];
  let maxUniqueCount = new Set(words[0]).size;

  for (let i = 1; i < words.length; i++) {
    const currentWord = words[i];
    const currentUniqueCount = new Set(currentWord).size;

    if (currentUniqueCount > maxUniqueCount) {
      maxUniqueCount = currentUniqueCount;
      maxWord = currentWord;
    } else if (currentUniqueCount === maxUniqueCount) {
      if (currentWord < maxWord) {
        maxWord = currentWord;
      }
    }
  }

  return maxWord;
};

